/* ============================================================
   Weather: the sky never sits still. Dry spells, drizzle, steady rain, full
   downpours with wind, lightning and thunder, and now and then the rain turns
   to snow that settles on the streets. Each spell lasts a minute or two and
   everything eases in and out: streets soak and dry slowly, snow builds up
   and melts away. The Look (theme) still sets the base colour and amount.
   ============================================================ */
const WX_STATES = {
  //          precip  snow  wind  storm   weight  duration (s)
  dry:      { p: 0.0,  s: 0, w: 0.15, st: 0, wt: 14, d: [50, 110] },
  drizzle:  { p: 0.32, s: 0, w: 0.2,  st: 0, wt: 22, d: [60, 130] },
  rain:     { p: 0.68, s: 0, w: 0.4,  st: 0, wt: 30, d: [70, 150] },
  downpour: { p: 1.0,  s: 0, w: 0.9,  st: 1, wt: 18, d: [45, 100] },
  snow:     { p: 0.62, s: 1, w: 0.3,  st: 0, wt: 16, d: [80, 160] },
};
const WX = {
  state: 'rain', t: 0, dur: 90,
  precip: 0.68, snow: 0, wind: 0.4, storm: 0,   // current (smoothed) values
  wet: 0.8, cover: 0,                            // surface state: how soaked, how snowed-over
  flash: 0, flashT: 8, gust: 0, thunder: [],
  forced: null,                                   // testing / debugging: set to a weather name to pin it
};
function wxPick() {
  const keys = Object.keys(WX_STATES).filter(k => k !== WX.state && !(WX.state === 'snow' && k === 'downpour'));
  let tot = 0; for (const k of keys) tot += WX_STATES[k].wt;
  let r = Math.random() * tot; for (const k of keys) { r -= WX_STATES[k].wt; if (r <= 0) return k; }
  return 'rain';
}
function wxSet(k) {
  const S = WX_STATES[k]; const prev = WX.state; WX.state = k; WX.t = 0; WX.dur = rand(S.d[0], S.d[1]);
  if (GAME.state === 'playing' && prev !== k) { const msg = { downpour: 'STORM ROLLING IN', snow: 'THE RAIN IS TURNING TO SNOW', dry: 'THE RAIN EASES OFF' }[k]; if (msg) GAME.toast(msg, '#bfe4ff'); }
}
function wxReset() { wxSet('rain'); WX.precip = 0.68; WX.snow = 0; WX.wind = 0.4; WX.storm = 0; WX.wet = 0.8; WX.cover = 0; WX.flash = 0; WX.thunder.length = 0; }

function updateWeather(dt) {
  WX.t += dt;
  if (!WX.forced && WX.t > WX.dur) wxSet(wxPick());
  const S = WX_STATES[WX.forced || WX.state], ease = (cur, want, tau) => cur + (want - cur) * (1 - Math.exp(-dt / tau));
  WX.precip = ease(WX.precip, S.p, 14); WX.snow = ease(WX.snow, S.s, 12); WX.wind = ease(WX.wind, S.w, 8); WX.storm = ease(WX.storm, S.st, 6);
  // streets soak in the rain (fast) and dry out slowly; snow settles over a minute and melts faster in rain
  const rainNow = WX.precip * (1 - WX.snow), snowNow = WX.precip * WX.snow;
  WX.wet = rainNow > 0.05 ? ease(WX.wet, 0.35 + 0.65 * Math.min(1, rainNow * 1.4), 18) : ease(WX.wet, 0.12, 110);
  WX.cover = snowNow > 0.1 ? ease(WX.cover, Math.min(1, snowNow * 1.5), 55) : ease(WX.cover, 0, rainNow > 0.1 ? 25 : 140);
  // gusts: the slant swings; heavier in storms
  WX.gust = Math.max(0, Math.sin(GAME.time * 0.37) * Math.sin(GAME.time * 0.113 + 2)) * WX.wind;
  NQU.uWind.value = WX.wind * 0.7 + WX.gust * 1.2;   // foliage sway (engine.js)
  // lightning in storms: a double flicker, thunder a few seconds later (sound travels)
  WX.flash = Math.max(0, WX.flash - dt * 3.2);
  if (WX.storm > 0.5) {
    WX.flashT -= dt;
    if (WX.flashT <= 0) {
      WX.flashT = rand(6, 16); WX.flash = 1; const dist = rand(0.6, 5);
      WX.thunder.push({ t: dist, k: 1.2 - dist / 6 });
      setTimeout(() => { WX.flash = Math.max(WX.flash, 0.7); }, 120);
    }
  }
  for (let i = WX.thunder.length - 1; i >= 0; i--) { const th = WX.thunder[i]; th.t -= dt; if (th.t <= 0) { AUD.thunder(th.k); WX.thunder.splice(i, 1); } }
  AUD.weather(rainNow, snowNow, WX.wind);
}
// what the renderer and effects read
function wxRainK() { return WX.precip * (1 - WX.snow); }
function wxSnowK() { return WX.precip * WX.snow; }

/* ============================================================
   Particles, dynamic lights, floating damage numbers
   ============================================================ */
const MAXP = 5000;
const PART = { n: 0, alive: 0, data: new Float32Array(MAXP * 8), p: [] };
for (let i = 0; i < MAXP; i++) PART.p.push({ x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1, r: 1, g: 1, b: 1, a: 1, size: 0.1, grav: 0, drag: 0, grow: 0, alive: false });
let _pi = 0;
function emit(x, y, z, vx, vy, vz, life, col, size, grav = 0, drag = 0, grow = 0, a = 1) {
  const p = PART.p[_pi]; _pi = (_pi + 1) % MAXP;
  p.x = x; p.y = y; p.z = z; p.vx = vx; p.vy = vy; p.vz = vz; p.life = life; p.max = life; p.r = col[0]; p.g = col[1]; p.b = col[2]; p.a = a;
  p.size = size; p.grav = grav; p.drag = drag; p.grow = grow; if (!p.alive) { p.alive = true; PART.alive++; } p.blood = false;
  return p;
}
function burst(x, y, z, n, col, speed, life, size, grav = 9, drag = 1, up = 0) {
  for (let i = 0; i < n; i++) {
    const u = Math.random() * 2 - 1, th = Math.random() * TAU, s = Math.sqrt(1 - u * u), sp = speed * (0.3 + Math.random() * 0.7);
    emit(x, y, z, Math.cos(th) * s * sp, u * sp + up, Math.sin(th) * s * sp, life * (0.5 + Math.random() * 0.5), col, size * (0.6 + Math.random() * 0.8), grav, drag);
  }
}
function updateParticles(dt) {
  let n = 0; const d = PART.data, P = PART.p, live = PART.alive; let seen = 0;
  for (let i = 0; i < MAXP && seen < live; i++) {   // stop once every live particle has been seen: the pool is mostly dead slots
    const p = P[i];
    if (!p.alive) continue;
    seen++;
    p.life -= dt; if (p.life <= 0) { p.alive = false; PART.alive--; continue; }
    p.vy -= p.grav * dt; const k = Math.max(0, 1 - p.drag * dt); p.vx *= k; p.vy *= k; p.vz *= k;
    p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
    if (p.y < 0.03 && p.grav > 0) {
      if (p.blood) { if (Math.random() < 0.3) addDecal(p.x, p.z, Math.abs(p.size) * rand(2.5, 5)); p.alive = false; PART.alive--; continue; }
      p.y = 0.03; p.vy *= -0.3; p.vx *= 0.6; p.vz *= 0.6;
    }
    p.size += p.grow * dt * Math.sign(p.size || 1);
    const t = p.life / p.max; const a = p.a * Math.min(1, t * 2.5);
    const o = n * 8; d[o] = p.x; d[o + 1] = p.y; d[o + 2] = p.z; d[o + 3] = p.r; d[o + 4] = p.g; d[o + 5] = p.b; d[o + 6] = a; d[o + 7] = p.size;
    n++;
  }
  PART.n = n;
}
// particle + rain GPU objects live in r3.js
const RAIN_N = 2600;

// dynamic lights (short-lived flashes + attached)
const DLIGHTS = [];
function flashLight(x, y, z, col, r, life) { DLIGHTS.push({ p: [x, y, z], c: col, r, life, max: life }); }
function updateLights(dt) { for (let i = DLIGHTS.length - 1; i >= 0; i--) { DLIGHTS[i].life -= dt; if (DLIGHTS[i].life <= 0) DLIGHTS.splice(i, 1); } }

// floating texts (screen-projected)
const FLOATS = [];
function floatText(x, y, z, text, color, size = 1, life = 0.9) { FLOATS.push({ x, y, z, text, color, size, life, max: life, vy: 1.4 }); if (FLOATS.length > 40) FLOATS.shift(); }
function updateFloats(dt) { for (let i = FLOATS.length - 1; i >= 0; i--) { const f = FLOATS[i]; f.life -= dt; f.y += f.vy * dt; f.vy *= 0.96; if (f.life <= 0) FLOATS.splice(i, 1); } }

// camera shake
const SHAKE = { amt: 0 };
