    for (const [ox, oz] of [[2.5, 0], [-2.5, 0], [0, 2.5], [0, -2.5]]) { const k = navIdx(p[0] + ox, p[1] + oz); if (k < 0 || NAV.block[k]) { ok = false; break; } }
